# Fixed readonly source-probe lease/runner. No COM activation or execution authority.
Set-StrictMode -Version Latest

function Get-P09XrefStageRunnerCode([string]$TemplateText) {
    Assert-P09XrefBinding ($TemplateText.Length -gt 0 -and $TemplateText.Length -le 32768) 'PROBE_TEMPLATE_TEXT_LIMIT'
    $algorithm=[Security.Cryptography.SHA256]::Create()
    try {$sha=([BitConverter]::ToString($algorithm.ComputeHash([Text.Encoding]::UTF8.GetBytes($TemplateText)))).Replace('-','').ToLowerInvariant()}
    finally {$algorithm.Dispose()}
    Assert-P09XrefBinding ($sha -ceq 'b6e6abfb685cd1af58426b17ed73793910747a8dbf2c51a81fab9f4d18e1ba36') 'PROBE_TEMPLATE_TEXT_SHA'
    $tokens=$null;$errors=$null
    $ast=[Management.Automation.Language.Parser]::ParseInput($TemplateText,[ref]$tokens,[ref]$errors)
    Assert-P09XrefBinding (@($errors).Count -eq 0) 'PROBE_TEMPLATE_PARSE'
    $functions=@($ast.FindAll({param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst]},$false))
    $support=@(foreach ($name in @('Assert-P09XrefWorker','Get-P09XrefWorkerDigest')) {
        $found=@($functions | Where-Object {$_.Name -ceq $name})
        Assert-P09XrefBinding ($found.Count -eq 1) 'PROBE_TEMPLATE_SUPPORT'
        $found[0].Extent.Text
    })
    $found=@($functions | Where-Object {$_.Name -ceq 'Invoke-P09XrefPreparationChild'})
    Assert-P09XrefBinding ($found.Count -eq 1) 'PROBE_TEMPLATE_RUNNER'
    $body=$found[0].Extent.Text;$marker='    $start=[Diagnostics.ProcessStartInfo]::new()'
    $at=$body.IndexOf($marker,[StringComparison]::Ordinal)
    Assert-P09XrefBinding ($at -gt 0 -and $body.IndexOf($marker,$at+$marker.Length,[StringComparison]::Ordinal) -lt 0) 'PROBE_TEMPLATE_BOUNDARY'
    $runner="function Invoke-P09XrefStageChild {`n"+
        "    `$Kind='source_stage_'+`$Stage`n"+
        "    `$file=`$Lease.binary`n"+
        "    `$childArguments=@('case',`$CaseIndex.ToString(),`$Stage,`$ExpectedSha256)`n"+$body.Substring($at)
    return [pscustomobject]@{support=$support;runner=$runner;capture_suffix=$body.Substring($at)}
}

function New-P09XrefProbeLease {
    $root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..\..'))
    $binary=Join-Path $root 'target/p09-149-conservative/debug/examples/p09_crossref_discovery_probe.exe'
    $template=Join-Path $PSScriptRoot 'inspect-crossref-worker-composition.ps1'
    $stream=$null;$algorithm=$null
    try {
        foreach ($path in @($binary,$template)) {
            $item=Get-Item -LiteralPath $path -Force
            Assert-P09XrefBinding ($item -is [IO.FileInfo] -and $item.Length -gt 0 -and
                $item.Length -le 16777216) 'PROBE_LEASE_FILE'
            $ancestor=$item
            while ($null -ne $ancestor) {
                Assert-P09XrefBinding (($ancestor.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0) 'PROBE_LEASE_LINK'
                if ($ancestor -is [IO.FileInfo]) {$ancestor=$ancestor.Directory} else {$ancestor=$ancestor.Parent}
            }
        }
        $templateItem=Get-Item -LiteralPath $template
        Assert-P09XrefBinding ($templateItem.Length -le 32768) 'PROBE_TEMPLATE_SIZE'
        $raw=[IO.File]::ReadAllBytes($template)
        $algorithm=[Security.Cryptography.SHA256]::Create()
        $templateSha=([BitConverter]::ToString($algorithm.ComputeHash($raw))).Replace('-','').ToLowerInvariant()
        Assert-P09XrefBinding ($templateSha -ceq 'b6e6abfb685cd1af58426b17ed73793910747a8dbf2c51a81fab9f4d18e1ba36') 'PROBE_TEMPLATE_SHA'
        $text=[Text.UTF8Encoding]::new($false,$true).GetString($raw)
        $code=Get-P09XrefStageRunnerCode $text
        Start-Sleep -Milliseconds 50
        $stream=[IO.File]::Open($binary,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
        Assert-P09XrefBinding ($stream.Length -eq 5112832) 'PROBE_BINARY_SIZE'
        $algorithm.Initialize();$watch=[Diagnostics.Stopwatch]::StartNew();$buffer=[byte[]]::new(65536);$count=0L
        while (($n=$stream.Read($buffer,0,$buffer.Length)) -ne 0) {
            $count+=$n;Assert-P09XrefBinding ($count -le 5112832) 'PROBE_BINARY_READ_LIMIT'
            [void]$algorithm.TransformBlock($buffer,0,$n,$buffer,0)
            $delay=[int][Math]::Ceiling(($count/1048576.0-$watch.Elapsed.TotalSeconds)*1000)
            if ($delay -gt 0) {Start-Sleep -Milliseconds $delay}
        }
        [void]$algorithm.TransformFinalBlock([byte[]]::new(0),0,0);$watch.Stop()
        $sha=([BitConverter]::ToString($algorithm.Hash)).Replace('-','').ToLowerInvariant()
        Assert-P09XrefBinding ($count -eq 5112832 -and $sha -ceq '0f9c727afa18d1c0145a21cbc63f947c48922873f6dbe97cd2860e76355491bb') 'PROBE_BINARY_SHA'
        $lease=[pscustomobject]@{root=$root;binary=$binary;stream=$stream;binary_sha256=$sha;template_sha256=$templateSha;
            template_text=$text;capture_suffix_sha256=([BitConverter]::ToString($algorithm.ComputeHash(
                [Text.Encoding]::UTF8.GetBytes($code.capture_suffix)))).Replace('-','').ToLowerInvariant();closed=$false}
        $stream=$null
        return $lease
    } finally {if ($null -ne $stream) {$stream.Dispose()};if ($null -ne $algorithm) {$algorithm.Dispose()}}
}

function Close-P09XrefProbeLease($Lease) {
    if ($null -ne $Lease -and -not $Lease.closed) {$Lease.stream.Dispose();$Lease.closed=$true}
}

function Invoke-P09XrefStageProbe {
    param([Parameter(Mandatory)]$Lease,[Parameter(Mandatory)][int]$CaseIndex,
        [Parameter(Mandatory)][string]$Stage,[Parameter(Mandatory)][string]$ExpectedSha256,
        [Parameter(Mandatory)][System.Collections.IDictionary]$Record)
    $Record.children=[Collections.Generic.List[object]]::new();$Record.error_code=$null
    try {
        Assert-P09XrefBinding ($Stage -cin @('opened','saved','reopened')) 'PROBE_STAGE'
        $scope=Get-P09XrefArtifactScope $CaseIndex ($Stage+'_clean') $ExpectedSha256
        $root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..\..'))
        $binary=Join-Path $root 'target/p09-149-conservative/debug/examples/p09_crossref_discovery_probe.exe'
        Assert-P09XrefBinding (-not $Lease.closed -and $Lease.stream -is [IO.FileStream] -and
            $Lease.stream.CanRead -and -not $Lease.stream.CanWrite -and $Lease.root -ceq $root -and
            $Lease.binary -ceq $binary -and $Lease.stream.Name -ceq $binary -and
            $Lease.binary_sha256 -ceq '0f9c727afa18d1c0145a21cbc63f947c48922873f6dbe97cd2860e76355491bb' -and
            $Lease.template_sha256 -ceq 'b6e6abfb685cd1af58426b17ed73793910747a8dbf2c51a81fab9f4d18e1ba36') 'PROBE_ACTIVE_LEASE'
        # Revalidate immutable template bytes, not caller-supplied executable code strings.
        $code=Get-P09XrefStageRunnerCode $Lease.template_text
        foreach ($definition in $code.support) {. ([scriptblock]::Create($definition))}
        . ([scriptblock]::Create($code.runner))
        $children=$Record.children
        $response=Invoke-P09XrefStageChild
        Assert-P09XrefBinding ($response.schema_version -ceq 'hwpx-agent.private.crossref-worker-source-probe/v1' -and
            $response.state -ceq 'source_probe_completed_not_native_attestation' -and
            $response.observed_output_sha256 -ceq $ExpectedSha256 -and
            $response.selected_case.case_id -ceq $scope.case_id -and $response.selected_case.phase -ceq $Stage -and
            $response.candidate_count -eq 8) 'PROBE_STAGE_RESPONSE'
        foreach ($name in @('native_execution_attested','native_target_resolution_qualified','parameter_key_semantics_qualified',
                'causal_insertion_or_preservation_proved','complete_reference_validation_qualified','native_execution_authorized',
                'raw_document_values_or_sdk_commands_present','p09_complete')) {
            Assert-P09XrefBinding ($response.$name -is [bool] -and -not $response.$name) 'PROBE_FALSE_CLAIM'
        }
        return $response
    } catch {
        $code=if ($_.Exception.Message -cmatch '^P09_XREF_(WORKER|BIND)_[A-Z_]+$') {$_.Exception.Message} else {'P09_XREF_BIND_STAGE_PROBE_FAILED_NO_RAW_VALUES'}
        $Record.error_code=$code;throw $code
    }
}

# Callback control flow only; callback completion never attests a native operation.
# Trusted native ports, producer binding, admission and resource guards are separate.
Set-StrictMode -Version Latest

function Get-P09XrefCaseFlowSteps {
    return @('prepare_slot','create_save_session','source_open','source_bind','opened_save','opened_probe',
        'sdk_insert','saved_save','saved_probe','save_session_close','create_reopen_session','fresh_saved_open',
        'reopened_save','reopened_probe','reopen_session_close','final_source_check')
}

function Invoke-P09XrefCaseFlow {
    param([Parameter(Mandatory)][int]$CaseIndex,[Parameter(Mandatory)][scriptblock]$StepExecutor,
        [Parameter(Mandatory)][scriptblock]$CleanupExecutor,[Parameter(Mandatory)][System.Collections.IDictionary]$State,
        [Parameter(Mandatory)][System.Collections.IDictionary]$Record)
    Assert-P09XrefBinding ($CaseIndex -ge 1 -and $CaseIndex -le 8) 'FLOW_CASE_INDEX'
    $Record.schema_version='hwpx-agent.crossref-case-callback-flow/v1'
    $Record.case_id='P09-XREF-BOOK-C'+$CaseIndex.ToString('00')
    $Record.state='callback_flow_started_unattested';$Record.phase=$null
    $Record.steps=[Collections.Generic.List[object]]::new();$Record.error_code=$null;$Record.cleanup_error_code=$null
    $Record.cleanup_callback_entered=$false;$Record.cleanup_callback_returned=$false
    $Record.native_execution_attested=$false;$Record.native_acceptance_attested=$false
    $Record.causal_insertion_or_preservation_proved=$false;$Record.accepted_count_delta=0;$Record.automatic_retry=$false
    try {
        foreach ($step in (Get-P09XrefCaseFlowSteps)) {
            $Record.phase=$step
            $entry=[ordered]@{step=$step;callback_entered=$true;callback_returned=$false}
            [void]$Record.steps.Add($entry)
            [void](& $StepExecutor $step $State)
            $entry.callback_returned=$true
        }
        $Record.state='all_callbacks_returned_native_effect_unattested'
    } catch {
        $Record.state='callback_flow_failed_native_effect_unattested'
        $Record.error_code=if ($_.Exception.Message -cmatch '^(P09_XREF_[A-Z_]+|P58_[A-Z_]+|STOP_[A-Z_]+)$') {
            $_.Exception.Message
        } else {'P09_XREF_BIND_FLOW_CALLBACK_FAILED_NO_RAW_VALUES'}
    } finally {
        $Record.cleanup_callback_entered=$true
        try {
            [void](& $CleanupExecutor $State)
            $Record.cleanup_callback_returned=$true
        } catch {
            $Record.cleanup_error_code=if ($_.Exception.Message -cmatch '^(P09_XREF_[A-Z_]+|P58_[A-Z_]+|STOP_[A-Z_]+)$') {
                $_.Exception.Message
            } else {'P09_XREF_BIND_FLOW_CLEANUP_FAILED_NO_RAW_VALUES'}
            if ($null -eq $Record.error_code) {$Record.state='callback_cleanup_failed_native_effect_unattested'}
        }
    }
    $Record.native_execution_attested=$false;$Record.native_acceptance_attested=$false
    $Record.native_cleanup_attested=$false;$Record.causal_insertion_or_preservation_proved=$false
    $Record.accepted_count_delta=0;$Record.p09_complete=$false
    # No state/provider data, document values, SDK commands or ownership proof is serialized here.
    # In particular cleanup_callback_returned is NOT cleanup_confirmed.
}

# Model flow and real readonly probe rejection only; no Hangul/native action.
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
. (Join-Path $PSScriptRoot 'crossref-owned-active-source.ps1')
. (Join-Path $PSScriptRoot 'crossref-owned-artifact.ps1')
. (Join-Path $PSScriptRoot 'crossref-save-reopen.ps1')
. (Join-Path $PSScriptRoot 'crossref-stage-probe.ps1')
. (Join-Path $PSScriptRoot 'crossref-case-flow.ps1')
$script:passed=0;$script:actualProbe=$null
function Invoke-P09XrefFlowTest([scriptblock]$Body) {& $Body;$script:passed++}
function Assert-P09XrefFlowReject([scriptblock]$Body) {
    $rejected=$false;try {& $Body} catch {$rejected=$true}
    Assert-P09XrefBinding $rejected 'TEST_FLOW_EXPECTED_REJECTION'
}
try {
    Invoke-P09XrefFlowTest {
        $expected='prepare_slot,create_save_session,source_open,source_bind,opened_save,opened_probe,sdk_insert,saved_save,saved_probe,save_session_close,create_reopen_session,fresh_saved_open,reopened_save,reopened_probe,reopen_session_close,final_source_check'
        Assert-P09XrefBinding (((Get-P09XrefCaseFlowSteps) -join ',') -ceq $expected) 'TEST_FIXED_FLOW_SEQUENCE'
        for ($i=1;$i -le 8;$i++) {
            $state=[ordered]@{seen=[Collections.Generic.List[string]]::new();cleanup=0};$record=[ordered]@{}
            Invoke-P09XrefCaseFlow $i {param($step,$s) [void]$s.seen.Add($step)} {param($s) $s.cleanup++} $state $record
            Assert-P09XrefBinding (($state.seen -join ',') -ceq $expected -and $state.cleanup -eq 1 -and
                $record.state -ceq 'all_callbacks_returned_native_effect_unattested' -and
                -not $record.native_execution_attested -and -not $record.native_acceptance_attested) 'TEST_MODEL_FLOW_NOT_NATIVE'
        }
    }
    Invoke-P09XrefFlowTest {
        $steps=Get-P09XrefCaseFlowSteps
        for ($i=0;$i -lt $steps.Count;$i++) {
            $state=[ordered]@{fail=$steps[$i];seen=[Collections.Generic.List[string]]::new();cleanup=0};$record=[ordered]@{}
            Invoke-P09XrefCaseFlow 1 {param($step,$s) [void]$s.seen.Add($step);if ($step -ceq $s.fail) {throw 'P09_XREF_BIND_TEST_STEP_FAILURE'}} {param($s) $s.cleanup++} $state $record
            Assert-P09XrefBinding ($state.seen.Count -eq ($i+1) -and $state.cleanup -eq 1 -and
                $record.steps.Count -eq ($i+1) -and -not $record.steps[$i].callback_returned -and
                $record.phase -ceq $steps[$i] -and -not $record.automatic_retry) 'TEST_EACH_FAILURE_STOPS_WITH_ONE_CLEANUP'
        }
    }
    Invoke-P09XrefFlowTest {
        $state=[ordered]@{};$record=[ordered]@{}
        Invoke-P09XrefCaseFlow 1 {throw 'private synthetic callback data'} {throw 'P58_OWNED_CLOSE_FAILED_NO_IMPLICIT_SAVE_OR_FORCE_KILL'} $state $record
        Assert-P09XrefBinding ($record.error_code -ceq 'P09_XREF_BIND_FLOW_CALLBACK_FAILED_NO_RAW_VALUES' -and
            $record.cleanup_error_code -ceq 'P58_OWNED_CLOSE_FAILED_NO_IMPLICIT_SAVE_OR_FORCE_KILL' -and
            -not $record.cleanup_callback_returned -and $record.state -ceq 'callback_flow_failed_native_effect_unattested') 'TEST_PRIMARY_AND_CLEANUP_FAILURES_PRESERVED'
        Assert-P09XrefBinding (($record | ConvertTo-Json -Depth 5 -Compress) -cnotmatch 'private synthetic') 'TEST_PRIVATE_FAILURE_REDACTED'
    }
    Invoke-P09XrefFlowTest {
        $state=[ordered]@{};$record=[ordered]@{}
        Invoke-P09XrefCaseFlow 1 {param($step,$s) $record.native_execution_attested=$true;$record.native_acceptance_attested=$true;$record.accepted_count_delta=1} {} $state $record
        Assert-P09XrefBinding (-not $record.native_execution_attested -and -not $record.native_acceptance_attested -and
            -not $record.native_cleanup_attested -and -not $record.p09_complete -and $record.accepted_count_delta -eq 0) 'TEST_CALLBACK_RETURN_CANNOT_PROMOTE_NATIVE_CLAIMS'
        Assert-P09XrefFlowReject {Invoke-P09XrefCaseFlow 0 {} {} ([ordered]@{}) ([ordered]@{})}
        Assert-P09XrefFlowReject {Invoke-P09XrefCaseFlow 9 {} {} ([ordered]@{}) ([ordered]@{})}
    }
    Invoke-P09XrefFlowTest {
        $path=Join-Path $PSScriptRoot 'inspect-crossref-worker-composition.ps1'
        $text=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($path))
        $code=Get-P09XrefStageRunnerCode $text
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($text,[ref]$tokens,[ref]$errors)
        $function=@($ast.FindAll({param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] -and
            $node.Name -ceq 'Invoke-P09XrefPreparationChild'},$false))[0]
        $marker='    $start=[Diagnostics.ProcessStartInfo]::new()';$original=$function.Extent.Text
        Assert-P09XrefBinding ($code.capture_suffix -ceq $original.Substring($original.IndexOf($marker,[StringComparison]::Ordinal)) -and
            $code.support.Count -eq 2 -and $code.runner.Contains("`$childArguments=@('case',`$CaseIndex.ToString(),`$Stage,`$ExpectedSha256)")) 'TEST_EXACT_QUALIFIED_CAPTURE_SUFFIX'
        Assert-P09XrefFlowReject {Get-P09XrefStageRunnerCode ($text+'changed')}
        Assert-P09XrefFlowReject {Get-P09XrefStageRunnerCode 'arbitrary code is not a template'}
    }
    $lease=New-P09XrefProbeLease
    try {
        Invoke-P09XrefFlowTest {
            Assert-P09XrefBinding (-not $lease.closed -and $lease.stream.CanRead -and -not $lease.stream.CanWrite) 'TEST_REAL_READ_LEASE'
            $writer=$null;$blocked=$false
            try {$writer=[IO.File]::Open($lease.binary,[IO.FileMode]::Open,[IO.FileAccess]::Write,[IO.FileShare]::ReadWrite)} catch {$blocked=$true}
            finally {if ($null -ne $writer) {$writer.Dispose()}}
            Assert-P09XrefBinding $blocked 'TEST_LEASE_DENIES_BINARY_WRITE_WITHOUT_WRITING'
        }
        Invoke-P09XrefFlowTest {
            $missing=0
            for ($i=1;$i -le 8;$i++) {if (-not (Test-Path -LiteralPath (Get-P09XrefCaseArtifactPath $i 'opened'))) {$missing=$i;break}}
            Assert-P09XrefBinding ($missing -gt 0) 'TEST_REAL_MISSING_ARTIFACT_REQUIRED'
            $record=[ordered]@{}
            Assert-P09XrefFlowReject {Invoke-P09XrefStageProbe $lease $missing 'opened' ('0'*64) $record}
            Assert-P09XrefBinding ($record.children.Count -eq 1 -and $record.children[0].exit_code -eq 2 -and
                $record.children[0].cleanup_confirmed -and $record.error_code -ceq 'P09_XREF_WORKER_PREPARATION_CHILD_FAILED') 'TEST_ACTUAL_MISSING_SOURCE_REJECTED_CHILD_CLEAN'
            Assert-P09XrefBinding (-not (Test-Path -LiteralPath (Get-P09XrefCaseArtifactPath $missing 'opened'))) 'TEST_NO_ARTIFACT_FABRICATION'
            $script:actualProbe=[ordered]@{case_index=$missing;children=@($record.children.ToArray());error_code=$record.error_code;
                missing_artifact_still_missing=$true;native_or_producer_attestation=$false}
        }
        Invoke-P09XrefFlowTest {
            $record=[ordered]@{}
            Assert-P09XrefFlowReject {Invoke-P09XrefStageProbe $lease 1 '../saved' ('a'*64) $record}
            Assert-P09XrefBinding ($record.children.Count -eq 0) 'TEST_INVALID_SELECTOR_BEFORE_CHILD'
        }
    } finally {Close-P09XrefProbeLease $lease}
    Invoke-P09XrefFlowTest {
        Close-P09XrefProbeLease $lease
        $record=[ordered]@{}
        Assert-P09XrefFlowReject {Invoke-P09XrefStageProbe $lease 1 'saved' ('a'*64) $record}
        Assert-P09XrefBinding ($lease.closed -and -not $lease.stream.CanRead -and $record.children.Count -eq 0) 'TEST_CLOSED_LEASE_REJECTS_BEFORE_CHILD'
    }
    Assert-P09XrefBinding ($script:passed -eq 9) 'TEST_EXACT_NINE_FLOW_PROBE'
    [ordered]@{state='nine_case_flow_stage_probe_contracts_pass_native_not_run';passed=$script:passed;failed=0;
        actual_readonly_missing_probe=$script:actualProbe;lease_closed=$lease.closed;
        native_session_started=$false;actual_native_case_executor_bound=$false;native_producer_qualified=$false;p09_complete=$false} | ConvertTo-Json -Depth 6 -Compress
    exit 0
} catch {
    $code=if ($_.Exception.Message -cmatch '^P09_XREF_(BIND|WORKER)_[A-Z_]+$') {$_.Exception.Message} else {'P09_XREF_BIND_FLOW_TEST_FAILED_NO_RAW_VALUES'}
    [ordered]@{state='case_flow_probe_contract_failed';passed=$script:passed;failed=1;error_code=$code;
        actual_readonly_missing_probe=$script:actualProbe;native_session_started=$false;p09_complete=$false} | ConvertTo-Json -Depth 6 -Compress
    exit 2
}
